    for x in states: boot+=ni[x]*VA[x]
    dm=r+gamma*boot-VA[s]
    Em={x:rho*(pres[x]+decay*EA[x]) for x in states}
    um=0.0
    for x in states: um+=Em[x]*WA[x]
    if un!=um:
        for x in states:
            pn=En[x]*W[x]; pm=Em[x]*WA[x]
            if pn!=pm or W[x]!=WA[x] or En[x]!=Em[x]:
                print("term",x,"prod",pn,pm,"W",W[x],WA[x],"E",En[x],Em[x])
        print("sum start types check; un/um",un,um)
        break
    nV={x:V[x]+alpha*un*(f[x]-gamma*(1-lam)*n[x]) for x in states}
    nW={x:W[x]+beta*(dn*En[x]-un*0+ -0 + (0)) for x in states}  # placeholder unused
    nW={x:W[x]+beta*(dn*En[x]-W[s]*f[x]) for x in states}
    mV={x:VA[x]+alpha*um*(pres[x]-repl*ni[x]) for x in states}
    mW={x:WA[x]+beta*(dm*Em[x]-WA[s]*pres[x]) for x in states}
    V,W=nV,nW; EB=En; VA,WA=mV,mW; EA=Em
    sB=s2; sA=envA.state
